def _t02(tid):
    t = _T01[tid]
    parts = [(ty, mt, cnt, dict(ex)) for ty, mt, cnt, ex in t[6]]
    if tid == "first_rankup":
        parts[0][3]["new"] = "true"            # LEAD: a NEW rank-up after the task became active
    if tid == "mini_boss":
        parts[0][3]["party"] = "true"          # Q7: one player kills the boss, every party member in that world gets the credit
