# setup / reload: the shipped tutorial is copied once (an owner's edits stay), then every quests/*.properties in name order; a line id
# seen twice keeps the first file. Returns the number of lines.
# 0.2 ONE-TIME UPDATE of the copied-once tutorial (PROJECT-RULES 4 rules): ONLY a file that is byte-for-byte the 0.1 shipped text is
# replaced - the old bytes go to quests/tutorial.properties.0.1.bak first (written + read back + compared, else nothing changes), then the
# 0.2 text. An edited file is KEPT and the 0.2 text is written ONCE beside it as tutorial.properties.0.2.new (a WARN). A file that already
# carries the 0.2 header (the run-once marker) is never touched. Returns a log text ("" = nothing done).
M(defs, r"""
public static String migrateTut(java.nio.file.Path tf) {
  try {
    if (!java.nio.file.Files.isRegularFile(tf, new java.nio.file.LinkOption[0])) return "";
    byte[] cur = java.nio.file.Files.readAllBytes(tf);
    byte[] v1 = TUTORIAL01.getBytes(java.nio.charset.StandardCharsets.UTF_8);
    String txt = new String(cur, java.nio.charset.StandardCharsets.UTF_8);
    if (txt.indexOf("Shipped by SkyyQuests 0.2") >= 0) return "";
    if (java.util.Arrays.equals(cur, v1)) {
      java.nio.file.Path bak = tf.resolveSibling("tutorial.properties.0.1.bak");
      @PKG@.QLog.writeAtomic(bak, TUTORIAL01);
      if (!java.util.Arrays.equals(java.nio.file.Files.readAllBytes(bak), cur)) {
        @PKG@.QLog.warn("quests/tutorial.properties NOT updated to 0.2: the 0.1 copy could not be kept (the file is used as it is; the next start tries again)");
        return "";
      }
      @PKG@.QLog.writeAtomic(tf, TUTORIAL);
      String m = "quests/tutorial.properties updated to the 0.2 tutorial (rewards by quest type, optional tasks, explore an area, a NEW rank-up, party boss credit) - the untouched 0.1 file is kept as quests/tutorial.properties.0.1.bak";
      @PKG@.QLog.info(m);
      return m;
    }
    java.nio.file.Path nw = tf.resolveSibling("tutorial.properties.0.2.new");
    if (java.nio.file.Files.exists(nw, new java.nio.file.LinkOption[0])) return "";
    @PKG@.QLog.writeAtomic(nw, TUTORIAL);
    String m2 = "quests/tutorial.properties was edited - KEPT as it is; the 0.2 tutorial (rewards by quest type, optional tasks, explore_area, party boss credit) is in quests/tutorial.properties.0.2.new - copy what you want (the NEW rank-up rule and Skip work with your file too)";
    @PKG@.QLog.warn(m2);
    return m2;
  } catch (Throwable t) { @PKG@.QLog.warn("could not check quests/tutorial.properties for the 0.2 update (the file is used as it is): " + t); return ""; }
}""")
