           "public static final String[] ADD_V = %s;" % jarr([_D02[k_] for k_ in M02_ADD]),
           "public static final String MARK = %s;" % jstr(M02_MARK), "public static final String MARK_ID = %s;" % jstr(M02_MARK_ID),
           "public static final String WHO = \"SkyyQuests 0.2\";", "public static volatile String LAST = \"\";",
