# the text step: null = the marker is there (ran before / a 0.2 file); else { text, change summary, kept notes, rows { key, old, new }* }
M(mig, r"""
public static Object[] update(String text, boolean tutGear) {
  String[] raw = text.split("\n", -1);
  java.util.ArrayList l = new java.util.ArrayList();
  for (int i = 0; i < raw.length; i++) {
    String s0 = raw[i];
    if (s0.endsWith("\r")) s0 = s0.substring(0, s0.length() - 1);
    l.add(s0);
  }
  int first = -1;
  java.util.HashSet seen = new java.util.HashSet();
  int k = 0;
  while (k < l.size()) {
    String s = (String) l.get(k);
    if (@PKG@.CfgFile.isComment(s)) { if (s.indexOf(MARK_ID) >= 0) return null; k++; continue; }
    int e = @PKG@.CfgFile.end(l, k);
    String key = @PKG@.CfgFile.key(s);
    if (key != null && key.startsWith("tutorial.reward.")) { if (first < 0) first = k; seen.add(key.substring(16)); }
    k = e + 1;
  }
  boolean crlf = text.indexOf("\r\n") >= 0;
  String nl = crlf ? "\r\n" : "\n";
  java.util.ArrayList out = new java.util.ArrayList();
  java.util.ArrayList rows = new java.util.ArrayList();
  java.util.ArrayList kept = new java.util.ArrayList();
  String chg = "";
  k = 0;
  while (k < l.size()) {
    String s2 = (String) l.get(k);
    if (@PKG@.CfgFile.isComment(s2)) { out.add(raw[k]); k++; continue; }
    int e2 = @PKG@.CfgFile.end(l, k);
    if (k == first) out.add(MARK + (raw[k].endsWith("\r") ? "\r" : ""));
    String key2 = @PKG@.CfgFile.key(s2);
    int ix = -1;
    if (key2 != null && key2.startsWith("tutorial.reward.")) for (int i = 0; i < KEYS.length; i++) if (KEYS[i].equals(key2.substring(16))) ix = i;
    if (ix >= 0) {
      String eff = @PKG@.CfgFile.value(l, k).trim();
      if (!tutGear && isCombat(KEYS[ix])) {
        if (e2 == k && same(eff, OLD[ix])) kept.add("tutorial.reward." + KEYS[ix] + "=" + @PKG@.CfgRows.oneLine(eff) + " kept - your edited quests/tutorial.properties has no gear reward for this combat task (the 0.2 gear rewards are in tutorial.properties.0.2.new)");
        for (int q = k; q <= e2; q++) out.add(raw[q]);
        k = e2 + 1;
        continue;
      }
      if (e2 == k && same(eff, OLD[ix])) {
        String cr = raw[k].endsWith("\r") ? "\r" : "";
        out.add(s2.substring(0, @PKG@.CfgFile.valStart(s2)) + NEW[ix] + cr);
        chg = chg + (chg.length() > 0 ? ", " : "") + KEYS[ix] + " " + eff + " -> " + NEW[ix];
        rows.add("quests.tutorial.rewards[" + KEYS[ix] + "]"); rows.add(cols(eff)); rows.add(cols(NEW[ix]));
        k = e2 + 1;
        continue;
      }
      if (e2 > k || !same(eff, NEW[ix])) kept.add("tutorial.reward." + KEYS[ix] + "=" + @PKG@.CfgRows.oneLine(eff) + " kept (custom) - the 0.2 default is " + NEW[ix]);
    }
    for (int q = k; q <= e2; q++) out.add(raw[q]);
    k = e2 + 1;
  }
  StringBuilder sb = new StringBuilder(text.length() + MARK.length() + 64);
  for (int i = 0; i < out.size(); i++) { if (i > 0) sb.append('\n'); sb.append((String) out.get(i)); }
  String body = sb.toString();
  if (first < 0) body = (body.length() == 0 || body.endsWith("\n")) ? body + MARK + nl : body + nl + MARK + nl;
  for (int i = 0; i < ADD.length; i++) {
    if (seen.contains(ADD[i])) continue;
    if (!(body.length() == 0 || body.endsWith("\n"))) body = body + nl;
    body = body + "tutorial.reward." + ADD[i] + "=" + ADD_V[i] + nl;
    chg = chg + (chg.length() > 0 ? ", " : "") + ADD[i] + " added (" + ADD_V[i] + ")";
    rows.add("quests.tutorial.rewards[" + ADD[i] + "]"); rows.add("(none)"); rows.add(cols(ADD_V[i]));
  }
  return new Object[] { body, chg, (String[]) kept.toArray(new String[0]), (String[]) rows.toArray(new String[0]) };
}""")
M(mig, r"""
public static Object[] update(String text) {
  return update(text, true);
}""")
M(mig, r"""
public static boolean saved(byte[] old) {
  String[] have = @PKG@.CfgHist.list(0);
  for (int i = have.length - 1; i >= 0; i--) {
    try { if (java.util.Arrays.equals(java.nio.file.Files.readAllBytes(@PKG@.CfgHist.bak(0, have[i])), old)) return true; } catch (Throwable x) { }
  }
  return false;
}""")
M(mig, r"""
public static synchronized String migrate02() {
  java.nio.file.Path f = @PKG@.QCfg.FILE;
  if (f == null) return "";
  try {
    if (!java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) return "";
    java.nio.file.Path done = f.resolveSibling(DONE);       // FIX (critic): a 2nd run-once marker beside the file - restoring the whole
    if (java.nio.file.Files.exists(done, new java.nio.file.LinkOption[0])) return "";      // pre-update History copy never re-runs it
    byte[] old = java.nio.file.Files.readAllBytes(f);
    Object[] r = update(new String(old, "ISO-8859-1"), tutGear());
    if (r == null) return "";
    byte[] data = ((String) r[0]).getBytes("ISO-8859-1");
    @PKG@.CfgRows.HOME = f.toAbsolutePath().getParent();
    if (@PKG@.CfgRows.LOG == null) @PKG@.CfgRows.LOG = @PKG@.QLog.LOG;
    @PKG@.CfgHist.init();
    @PKG@.CfgLog.init();
    @PKG@.CfgHist.snapshot(0, old, @PKG@.CfgHist.stamp(), WHO, "before the 0.2 tutorial rewards update");
    if (!saved(old)) {
      @PKG@.QLog.warn("config.properties NOT updated to the 0.2 tutorial rewards: the old file could not be kept in " + @PKG@.CfgHist.DIR + " (the file is used as it is; the next start tries again)");
      return "";
    }
    @PKG@.CfgRows.atomicWrite(f, data);
    String[] rows = (String[]) r[3];
    for (int q = 0; q + 2 < rows.length; q = q + 3) {
      @PKG@.CfgLog.enqueue(@PKG@.CfgLog.now() + "\t" + WHO + "\t-\tupdate\t" + rows[q] + "\t" + rows[q + 1] + "\t" + rows[q + 2] + "\tok");
    }
    if (rows.length > 0) @PKG@.CfgLog.flush();
    try { @PKG@.QLog.writeAtomic(done, "SkyyQuests 0.2: config.properties got the one-time tutorial reward update - delete this file only to run it again\n"); }
    catch (Throwable x) { @PKG@.QLog.warn("could not write " + DONE + " (the marker inside config.properties still stops a re-run): " + x); }
    String chg = (String) r[1];
    String[] kept = (String[]) r[2];
    String msg = chg.length() > 0
      ? "config.properties updated to the 0.2 tutorial rewards: " + chg + " (Skyy 2026-10-13: combat quests pay class gear, the rest items + coins; the old file is in config-history; Server Setup -> Changes can undo it)"
      : "config.properties: no tutorial reward line held a 0.1 default - nothing changed (0.2 marker added)";
    @PKG@.QLog.info(msg);
    StringBuilder all = new StringBuilder(msg);
    for (int i = 0; i < kept.length; i++) { @PKG@.QLog.info(kept[i]); all.append("; ").append(kept[i]); }
    LAST = all.toString();
    return LAST;
  } catch (Throwable t) {
    @PKG@.QLog.warn("could not update config.properties to the 0.2 tutorial rewards (the file is used as it is): " + t);
    return "";
  }
}""")

